      const brBox = { x: brX, y: cursor + span / 2 - brH / 2, w: brW, h: brH };
      const mid = brBox.y + brH / 2;
      brMids.push(mid);
      ctx.line(spineX, mid, brX, mid, { color: colors.muted, width: 1 });
